import { test } from 'node:test'
import assert from 'node:assert/strict'
import { Inventory } from '../src/inventory.js'
import { summary, render } from '../src/report.js'
const dated = () => Inventory.fromFile().list()
const undated = () => [
  ...dated(),
  { id: 'n1', title: 'New One', author: 'A', priceCents: 1000, stock: 4, tags: [] },
  { id: 'n2', title: 'New Two', author: 'B', priceCents: 1000, stock: 7, tags: [], published: null },
]
test('undated books land in a final Unknown decade row', () => {
  const s = summary(undated(), { generatedAt: '2026-01-01' })
  const last = s.decades[s.decades.length - 1]
  assert.deepEqual(last, { decade: 'Unknown', titles: 2, units: 11 })
  assert.deepEqual(s.decades.slice(0, -1).map((d) => d.decade), ['1970s', '1980s', '1990s', '2000s', '2010s'])
  const md = render(undated(), 'markdown', { generatedAt: '2026-01-01' })
  assert.match(md, /\| Unknown \| 2 \| 11 \|/)
  const rows = md.split('\n').filter((l) => /^\| (\d{4}s|Unknown) \|/.test(l))
  assert.equal(rows[rows.length - 1].startsWith('| Unknown'), true)
  const all = summary(dated(), { generatedAt: '2026-01-01' })
  assert.equal(all.decades.some((d) => d.decade === 'Unknown'), false)
  assert.doesNotMatch(render(dated(), 'markdown', { generatedAt: '2026-01-01' }), /Unknown/)
})

